#nullable enable // autogenerated

using System;
using System.Linq;
using MVZ2.Metas;
using MVZ2.Modding;
using MVZ2Logic.Games;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Managers
{
    public partial class ResourceManager : MonoBehaviour
    {
        #region 元数据列表
        public CurseMetaList? GetCurseMetaList(string nsp)
        {
            var modResource = main.ResourceManager.GetModResource(nsp);
            if (modResource == null)
                return null;
            return modResource.CurseMetaList;
        }
        public CurseMeta[] GetModCurseMetas(string nsp)
        {
            var metaList = GetCurseMetaList(nsp);
            if (metaList == null)
                return Array.Empty<CurseMeta>();
            return metaList.metas.ToArray();
        }
        #endregion

        #region 元数据
        public string GetCurseName(NamespaceID curseID)
        {
            return Main.Game.GetCurseName(curseID);
        }
        public string GetCurseTooltip(NamespaceID curseID)
        {
            return Main.Game.GetCurseTooltip(curseID);
        }
        #endregion
        private void LoadUnlocks_Curses(ModResource resource)
        {
            if (resource.CurseMetaList == null)
                return;
            foreach (var meta in resource.CurseMetaList.metas)
            {
                AddConditionListUnlocks(meta.UnlockConditions);
            }
        }
    }
}
